import json
f='/Users/kenneth/.claude/projects/-Users-kenneth-Projects-JusPrin/4dd7461d-dd64-4d02-9eb4-be3a58c5e029.jsonl'
for line in open(f):
    try: e=json.loads(line)
    except: continue
    m=e.get('message',{})
    c=m.get('content')
    texts=[]
    if isinstance(c,str): texts=[c]
    elif isinstance(c,list):
        for p in c:
            if p.get('type')=='text': texts.append(p['text'])
            if p.get('type')=='tool_result':
                cc=p.get('content')
                if isinstance(cc,str): texts.append(cc)
    for t in texts:
        low=t.lower()
        if 'canvas' in low and ('publish' in low) and ('never' in low or "don't" in low or 'do not' in low or 'not publish' in low):
            i=low.find('canvas'); print(e.get('type'), e.get('timestamp'), '::', t[max(0,i-400):i+400].replace('\n',' ')); print('----')
EOF

