// The Agent page in its OrcaSlicer import mode (?panel=orca-import): the
// window File › Import › Import from OrcaSlicer… opens. It speaks the same
// bridge as the welcome-back window; each button is a shell_action the
// window carries out (Home/OrcaImportWindow.cpp).

import { useEffect, useMemo, useReducer } from 'react';
import { BridgeClient, Transport } from './bridge/client';
import { initialState, reducer } from './state/store';
import { applyAppearance } from './tokens';
import { BridgeErrorPane, ConnectingPane } from './components/Panels';
import { OrcaImport, OrcaImportActions } from './components/OrcaImport';

export function OrcaImportApp({ getTransport }: { getTransport: () => Transport | null }) {
  const [state, dispatch] = useReducer(reducer, initialState);

  const client = useMemo(
    () =>
      new BridgeClient({
        getTransport,
        onConnectionChange: (connection, detail) => dispatch({ kind: 'connection', state: connection, detail }),
        onEnvelope: (envelope) => dispatch({ kind: 'host', envelope }),
      }),
    // The transport is fixed for the lifetime of the page.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  );

  useEffect(() => {
    client.start();
  }, [client]);

  useEffect(() => {
    applyAppearance(state.appearance);
  }, [state.appearance]);

  const actions = useMemo<OrcaImportActions>(
    () => ({
      importPrinters: (printers) => client.send('shell_action', { action: 'import', printers }),
      chooseFolder: () => client.send('shell_action', { action: 'choose_folder' }),
      close: () => client.send('shell_action', { action: 'close' }),
    }),
    [client],
  );

  if (state.connection !== 'connected' && state.connection !== 'connecting') {
    return (
      <div className="app">
        <BridgeErrorPane title="This window could not reach JusPrin" detail={state.connectionDetail}
          diagnostics={state.diagnostics} onRetry={() => client.retry()} />
      </div>
    );
  }
  if (!state.orcaImport) return <div className="app"><ConnectingPane /></div>;

  return (
    <div className="app app--orca-import">
      <OrcaImport state={state.orcaImport} actions={actions} />
    </div>
  );
}

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { App } from './App';
import { PreferencesApp } from './PreferencesApp';
import { WelcomeApp } from './WelcomeApp';
import { OrcaImportApp } from './OrcaImportApp';
import { nativeTransport } from './bridge/client';
import { applyAppearance, applyStaticTokens } from './tokens';
import './styles.css';

applyStaticTokens();
applyAppearance('light');

const query = new URLSearchParams(window.location.search);
// The temporary printer task chat loads the same page with ?panel=printer: the same
// thread and composer, with the printer session's card pinned above them
// instead of the project's setup card. See App.tsx.
const panel = query.get('panel') === 'printer';
// JusPrin's Preferences window loads it with ?panel=preferences: its own
// surface, drawn with the same Agent connection rows. See PreferencesApp.tsx.
const preferences = query.get('panel') === 'preferences';
// The window shown once after JusPrin v1's setup was imported loads it with
// ?panel=welcome. See WelcomeApp.tsx.
const welcome = query.get('panel') === 'welcome';
// File › Import › Import from OrcaSlicer…'s window loads it with
// ?panel=orca-import. See OrcaImportApp.tsx.
const orcaImport = query.get('panel') === 'orca-import';

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    {preferences
      ? <PreferencesApp getTransport={nativeTransport} />
      : welcome
        ? <WelcomeApp getTransport={nativeTransport} />
        : orcaImport
          ? <OrcaImportApp getTransport={nativeTransport} />
          : <App getTransport={nativeTransport} printerPanel={panel} />}
  </StrictMode>,
);
